import json
OT=solve(T)  # T, solve persist
# self-verify: every changed cell is interior to a maximal rect of a marker component
R=rects_of(T)
from collections import defaultdict
interior=defaultdict(set)
for (i,j,h,w) in R:
    for a in range(i+1,i+h-1):
        for b in range(j+1,j+w-1):
            interior[(a,b)].add((i,j,h,w))
lab=[[-1]*30 for _ in range(30)]; n=0
for i in range(30):
    for j in range(30):
        if T[i][j] and lab[i][j]<0:
            dq=deque([(i,j)]); lab[i][j]=n
            while dq:
                a,b=dq.popleft()
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<30 and 0<=y<30 and T[x][y] and lab[x][y]<0:
                        lab[x][y]=n; dq.append((x,y))
            n+=1
mcomp={}
for i in range(30):
    for j in range(30):
        if T[i][j] not in (0,1): mcomp[lab[i][j]]=T[i][j]
bad=[]
for a in range(30):
    for b in range(30):
        if OT[a][b]!=T[a][b]:
            ok = lab[a][b] in mcomp and any(lab[i][j]==lab[a][b] for (i,j,h,w) in interior[(a,b)])
            if not ok: bad.append((a,b))
print("unjustified changed cells:", bad)
# also verify unchanged cells that are interior to marker rects? (shouldn't happen)
miss=[]
for a in range(30):
    for b in range(30):
        rs=[(i,j,h,w) for (i,j,h,w) in interior[(a,b)] if lab[i][j] in mcomp and lab[i][j]==lab[a][b]]
        if rs and OT[a][b]==1: miss.append((a,b))
print("missed fills:", miss)
lines=[','.join(map(str,r)) for r in OT]
for idx,l in enumerate(lines):
    print(f"{idx:02d} cksum={sum(r*(k+1) for k,r in enumerate(OT[idx]))%997:04d} {l}")

# print grid in 10-value chunks with indices for reliable transcription
for a in range(30):
    chunks=[]
    for c0 in (0,10,20):
        chunks.append(f"[{c0}]"+','.join(map(str,OT[a][c0:c0+10])))
    print(a,'|'+'|'.join(chunks))
